function render(){
audioSync();
if(screen==='exterior'){app.innerHTML=`<main class="exterior-opening ${entering?'is-entering':''}">${exterior()}<div class="outside-top"><a class="outside-brand" aria-label="Cozy Café">Cozy Café<span>LITTLE MOMENTS</span></a>${musicButton()}<span class="outside-level">LEVEL ${level()} · ${level()===1?'Humble tea stall':level()===2?'Neighborhood café':level()===3?'Lakeside restaurant':'Grand luxury hotel'}</span></div><section class="outside-welcome"><span class="eyebrow">YOUR LITTLE CORNER OF THE WORLD</span><h1>${state.name?`Good morning, ${esc(state.name)}.`:'Your café story starts here.'}</h1><p>${level()===1?'A borrowed corner, a kettle, and a dream. Every cup helps you grow.':'You built this, one cup at a time. Welcome to your growing café.'}</p><label class="welcome-name-label" for="owner">What should your customers call you?</label><input class="welcome-name" id="owner" type="text" maxlength="24" autocomplete="given-name" placeholder="Enter your name" value="${esc(state.name)}" ${entering?'disabled':''}><button class="primary" data-action="enter" ${entering?'disabled':''}>${entering?level()===1?'Opening the stall…':'Opening the door…':level()===1?'Open the tea stall →':'Open the café →'}</button><small>${level()===1?'Three unique customers per level · Random orders':'Progress saved automatically on this device'}</small>${state.seenIntro&&!reviewSave?'<button class="welcome-reset" data-action="reset">Start a new game</button>':''}</section><button class="review-launch" data-action="levels">${reviewSave?'Review session · ':''}Level selection · temporary</button>${modal?modalHTML():''}</main>`;return}
const o=state.orders.find(o=>o.id===selected),r=o&&recipe(o);
if(o){busy=!!o.action;app.innerHTML=preparation(o);return}
busy=false;
const current=o||state.orders.find(x=>x.id===focusId)||state.orders[0];
const portrait=['male','elias','student-female','student-male','family','business','senior','travellers','executive-woman','executive-man','delegation'].includes(current?.portrait)?current.portrait:'female';
app.innerHTML=`<main class="immersive-game ${o?'is-cooking':''} ${modal?'menu-open':''}"><div class="world-scene ${current?'has-customer':''}"><img src="assets/${current?'customer-'+portrait:level()>=4?'level4-counter-empty':level()>=3?'level3-counter-empty':level()>1?'level2-counter-empty':'counter-empty'}.webp" alt="${current?esc(current.name)+' at your café counter':'Lakeside walking path viewed from inside your café'}"></div><div class="world-shade"></div><header class="game-hud glass"><div class="brand">Cozy Café<small>LITTLE MOMENTS</small></div><div class="level-hud"><div class="row"><b>Level ${level()}</b><small>${state.visitsFinished}/3 visits</small></div><div class="xp"><i style="width:${state.visitsFinished/3*100}%"></i></div></div><div class="stats"><div><span class="eyebrow">Cash</span><b>$${state.cash}</b></div><div><span class="eyebrow">Served</span><b>${state.served}</b></div><div class="rep"><span class="eyebrow">Reputation</span><b>${state.rep}%</b></div></div>${musicButton()}<button data-action="pause" aria-label="Pause game">Ⅱ Pause</button></header><nav class="game-nav glass"><button data-action="recipes">Recipe book</button><button data-action="shop">Upgrades</button><button data-action="exterior">My café</button><button data-action="levels">${reviewSave?'Review · ':''}Levels · temporary</button></nav>
${state.orders.length>1&&!current?.group?`<aside class="queue glass"><span class="eyebrow">AT THE COUNTER · ${state.orders.length}</span>${state.orders.map(x=>`<button class="queue-order ${x.id===current?.id?'selected':''}" data-action="focus" data-id="${x.id}">${esc(x.name)} · ${recipe(x).icon}<small>${x.step}/${recipe(x).steps.length} steps</small></button>`).join('')}</aside>`:''}
${!o?current?current.group?familyOrderCard(current):`<section class="main-order glass" aria-label="Current customer order"><div class="row"><span class="eyebrow">${current.step?'ORDER IN PROGRESS':'A LITTLE MOMENT TO MAKE'}</span><span class="order-status" data-status="${current.id}">${current.remaining<=0?'Late':current.step===recipe(current).steps.length?'Ready to serve':current.step?'Preparing':'Waiting'}</span></div><p class="order-customer">For ${esc(current.name)}</p><div class="order-item"><span class="order-drink-visual" aria-hidden="true">${drinkPreview(recipe(current))}</span><div><h2>${recipe(current).name}</h2><small>$${recipe(current).price} + up to $${recipe(current).tip} tip</small></div></div><div class="clock" data-bar="${current.id}"><i style="width:${Math.max(0,current.remaining/current.duration*100)}%"></i></div><div class="row order-time"><span data-time="${current.id}">${timeText(current)}</span><small>${state.relaxed?'Relaxed mode':'Serve early for a bigger tip'}</small></div><button class="primary wide" data-action="select" data-id="${current.id}">${current.step===recipe(current).steps.length?'Ready to serve':current.step?'Continue preparing':'Prepare order'} →</button>${state.tutorial===0?'<p class="order-hint">Start here. Choose the right ingredients and follow the recipe from memory.</p>':''}</section>`:'<section class="waiting-card glass"><span class="eyebrow">A QUIET LITTLE MOMENT</span><h2>Ready for the next hello.</h2><p>Your next customer is on the way.</p></section>':''}
${o?`<div class="kitchen glass cooking-panel"><div class="row"><div><span class="eyebrow">PREPARING FOR ${esc(o.name)}</span><h2 style="margin:5px 0 0">${r?r.name:'Ready when you are.'}</h2></div><div style="text-align:right"><button class="back-counter" data-action="counter">← Back to customer</button><br><span class="eyebrow">${o?esc(o.name)+'’S ORDER':'WELCOME, '+esc(state.name)}</span><div style="margin-top:6px" id="prep-clock">${o?timeText(o):'Your next little moment awaits.'}</div></div></div>${r?`<div class="steps">${r.steps.map((s,i)=>`<span class="step ${i<o.step?'done':i===o.step?'current':''}">${i<o.step?'✓':i+1} ${s}</span>`).join('')}</div>`:'<p class="muted" style="margin:15px 0">Choose an order to bring it to your preparation station.</p>'}<div class="board" id="board" role="button" tabindex="0" aria-label="Preparation board; place selected ingredient"><div class="assembled">${r?r.steps.slice(0,o.step).map(s=>`<span class="piece">${ICONS[s]} ${s}</span>`).join(''):''}</div><span id="board-help" class="muted">${!o?'A fresh start, one order at a time.':o.step===r.steps.length?'Ready for a happy customer.':busy?'Preparing…':`Drop ${r.steps[o.step].toLowerCase()} here`}</span>${o&&o.step===r.steps.length?`<button class="primary" data-action="serve" data-id="${o.id}">Serve to ${esc(o.name)} →</button>`:''}<div class="hands"><i class="hand"></i><i class="hand"></i></div></div><div class="tray">${r&&o.step<r.steps.length?[...new Set(r.steps)].map(s=>`<button class="ingredient" data-ingredient="${s}" ${busy?'disabled':''}><span>${ICONS[s]}</span>${s}</button>`).join(''):''}</div><div class="footnote"><span>↗ Drag to prepare · Select + tap also works</span><span>${state.relaxed?'RELAXED MODE · NO DEADLINES':'LIVE ORDERS · TIMERS KEEP RUNNING'}</span></div></div>`:''}<div class="ambient-label glass">${o?'Follow the recipe · Your customer is waiting':state.combo?state.combo+' happy customers in a row':'One cup at a time.'}</div>${modal?modalHTML():''}</main>`;
}

function timeText(o){return o.remaining>0?`${Math.ceil(o.remaining)}s remaining`:`Late · leaves in ${Math.max(0,Math.ceil(20+o.remaining))}s`}
function orderTicket(o){const r=recipe(o);return `<button class="ticket ${o.id===selected?'active':''}" data-action="select" data-id="${o.id}"><div class="row"><b>${esc(o.name)}</b><small data-status="${o.id}">${o.remaining<=0?'Late':o.step===r.steps.length?'Ready to serve':o.step?'Preparing':'Waiting'}</small></div><strong>${r.icon} ${r.name}</strong><div class="row"><span>$${r.price} + up to $${r.tip} tip</span></div><div class="clock" data-bar="${o.id}"><i style="width:${Math.max(0,o.remaining/o.duration*100)}%"></i></div><div class="row" style="margin-top:8px"><span data-time="${o.id}">${timeText(o)}</span><small>${o.step}/${r.steps.length}</small></div></button>`}
function exterior(){if(level()===1)return `<div class="cafe-art humble"><img src="assets/stall-empty.webp" alt="A tiny clean cream-and-blue tea stall with a polished kettle, neat cups, a wooden stool and a bicycle beside the lake" fetchpriority="high">${state.upgrades.includes('plants')?'<div class="garden-extra" aria-label="Purchased greenery">🪴</div>':''}</div>`;return `<div class="cafe-art ${level()>=10?'expanded':level()>=5?'growing':''}"><img src="assets/${level()>=4?'level4-exterior':level()>=3?'level3-exterior':'level2-scooter-empty'}.webp" alt="${level()>=4?'An ultra luxury hotel with luxury cars and a rooftop helipad with helicopter':level()>=3?'A larger lakeside restaurant with a terrace and an unbranded premium navy car':'Lakeside café with an unbranded sage scooter'}" fetchpriority="high">${state.upgrades.includes('plants')?'<div class="garden-extra" aria-label="Purchased greenery">🪴 🌿 🪴</div>':''}${level()>=10?'<div class="expansion-sign">GARDEN TERRACE<br><small>Now open · Level 10</small></div>':''}</div>`}
function modalHTML(){let body='';if(modal==='pause')body=`<h2>A little breather.</h2><p class="muted">The café is paused. Take your time.</p><div class="panel">${esc(state.name)} · Café owner<br><small>Level ${level()} · ${state.served} served · $${state.tips} tips earned</small></div><label class="setting">Relaxed mode <input type="checkbox" data-setting="relaxed" ${state.relaxed?'checked':''}></label><small>Freezes deadlines; customer arrivals continue.</small><label class="setting">Background music <input type="checkbox" data-setting="music" ${state.music?'checked':''}></label><label class="setting">Sound effects <input type="checkbox" data-setting="sound" ${state.sound?'checked':''}></label><button data-action="test-audio">Test sound</button><button class="primary wide" data-action="close">Back to my café</button><button style="margin-top:12px" data-action="reset">Start a new game</button>`;
if(modal==='complete')body=`<h2>Your café dream came true.</h2><p>All four levels completed — three unique customer visits in each chapter.</p><p>${state.served} dishes served · $${state.cash} earned · ${state.xp} XP</p><button class="primary wide" data-action="reset">Play a new café story</button>`;
if(modal==='levels')body=levelReviewPanel();
if(modal==='reset')body=`<h2>Start fresh?</h2><p>This clears the café’s progress saved in this browser.</p><button data-action="close">Keep my café</button> <button data-action="confirm-reset">Reset progress</button>`;
if(modal==='shop')body=`<h2>A little room to grow.</h2><p class="muted">Your balance: $${state.cash} · Game paused while browsing</p>${UPGRADES.map(u=>`<div class="shop-item row"><div><b>${u.name}</b><p>${u.desc}</p><small>Available at level ${u.level}</small></div><button data-action="buy" data-id="${u.id}" ${state.upgrades.includes(u.id)||state.cash<u.cost||level()<u.level?'disabled':''}>${state.upgrades.includes(u.id)?'Owned':'$'+u.cost}</button></div>`).join('')}`;
if(modal==='recipes')body=`<h2>Made with a little love.</h2><p class="muted">Level 1: kettle-brewed teas and instant coffees. After three customer visits, unlock your larger café, espresso coffee, sandwiches and croissants. After Level 2’s three visits, Level 3 adds pizza, pasta and grilled mushroom melts. After Level 3’s three visits, Level 4 opens your grand hotel and luxury menu.</p>${RECIPES.map(r=>`<div class="shop-item"><div class="row"><b>${r.icon} ${r.name}</b><span>${level()>=r.level?'Available':'Level '+r.level+' · Locked'}</span></div><p>${r.steps.join(' → ')}</p><small>$${r.price} + up to $${r.tip} tip · ${r.time}s deadline</small></div>`).join('')}`;
if(modal==='exterior')body=`<div class="exterior exterior-gallery"><h2>Your corner of the world.</h2><span class="badge">LEVEL ${level()}</span>${exterior()}<p>Level 1 · A tiny tea stall and bicycle.<br>Level 2 · After three visits, a beautiful café and a bigger menu.<br>Level 3 · After three more visits, a larger restaurant, premium car and chef’s menu. Level 4 · After three more visits, a luxury hotel, cars, helicopter and fine dining menu.</p><small>Equipment: ${state.upgrades.length} upgrades owned.</small></div>`;
if(modal==='level')body=`<div style="text-align:center"><span class="badge">A NEW CHAPTER</span><h2 style="margin-top:20px">Welcome to level ${level()}.</h2>${[2,3,4].includes(level())?'<div class="level-reveal">'+exterior()+'</div><p>'+ (level()===4?'Welcome to your grand hotel, with luxury parking, a rooftop helipad and fine dining.':level()===3?'Your café is now a lakeside restaurant. A bigger kitchen, a premium car and a new chef’s menu await.':'Your tiny tea stall is now a beautiful café.')+'</p>':''}<p>${RECIPES.filter(r=>r.level===level()).map(r=>r.icon+' '+r.name+' is now on the menu.').join(' ')||'Your café is growing, one happy customer at a time.'}</p><p class="muted">${level()%2===1&&level()<=5?'Three new customer visits await.':''}</p><button class="primary" data-action="close">Keep the good things going →</button></div>`;
return `<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${modal}"><div style="text-align:right;margin-bottom:8px"><button data-action="close" aria-label="Close menu">✕</button></div>${body}</section></div>`}
function addOrder(first=false){
 const lv=level();if(!reviewSave&&(state.journeyComplete||state.visitsStarted>=3))return;if(state.orders.length)return;const index=reviewSave?state.customerSequence++:state.visitsStarted++;state.customerSequence=state.visitsStarted;
 const customers=lv===1?[{name:'Mia',portrait:'female'},{name:'Oliver',portrait:'male'},{name:'Elias',portrait:'elias'}]:lv>=4?[{name:'Vivienne',portrait:'executive-woman'},{name:'Gabriel',portrait:'executive-man'},{name:'The business lunch',portrait:'delegation'}]:lv>=3?[{name:'Anika',portrait:'business'},{name:'Arthur',portrait:'senior'},{name:'Nora & Mateo',portrait:'travellers'}]:[{name:'Mei',portrait:'student-female'},{name:'Jordan',portrait:'student-male'},{name:'The Park family',portrait:'family'}];
 const customer=reviewSave?customers[['family','travellers','delegation'].includes(reviewRecipe)?2:reviewRecipe&&lv>1?index%2:index%3]:customers.find(c=>!state.seenPortraits.includes(c.portrait));if(!customer)return;state.seenPortraits.push(customer.portrait);
 if(['family','travellers','delegation'].includes(customer.portrait)){
 const group=crypto.randomUUID(),isFriends=customer.portrait==='travellers',isDelegation=customer.portrait==='delegation',duration=(isDelegation?270:isFriends?145:160)+(state.upgrades.includes('seating')?15:0)+(state.upgrades.includes('station')?15:0);
 (isDelegation?['truffle-risotto','lobster-pasta','chocolate-fondant']:isFriends?['pizza','pasta','mushroom-melt']:['sandwich','cheese-tomato','coffee','croissant','tea']).map(id=>({id,sort:Math.random()})).sort((a,b)=>a.sort-b.sort).slice(0,isFriends?2:3).map(x=>x.id).forEach((id,i)=>state.orders.push({id:crypto.randomUUID(),...customer,group,member:(isDelegation?['Asha','Edward','Karim']:isFriends?['Nora','Mateo']:['Dad','Mum','Child'])[i],recipe:id,step:0,duration,remaining:duration}));
 }else{
 const unlocked=RECIPES.filter(r=>r.level<=lv),previous=state.lastRecipe;
 const pool=lv>=4?unlocked.filter(r=>['truffle-risotto','lobster-pasta','chocolate-fondant'].includes(r.id)):lv>=3?unlocked.filter(r=>['pizza','pasta','mushroom-melt'].includes(r.id)):lv===2?unlocked.filter(r=>r.level===2):unlocked;
 const choices=pool.filter(r=>r.id!==previous);
 const r=reviewRecipe?RECIPES.find(r=>r.id===reviewRecipe):first&&!previous&&lv===1?RECIPES.find(r=>r.id==='tea'):(choices.length?choices:pool)[Math.floor(Math.random()*(choices.length||pool.length))];
 state.lastRecipe=r.id;const duration=r.time+(state.upgrades.includes('seating')?15:0)+(state.upgrades.includes('station')?15:0);
 state.orders.push({id:crypto.randomUUID(),...customer,recipe:r.id,step:0,duration,remaining:duration});
 }
 reviewRecipe=null;sound(700);render();
}
function startAutomaticStep(o){const step=recipe(o).steps[o.step],action=AUTOMATIC_STEPS[step];if(o.action||!action)return false;o.action=step;CafeAudio.preparation(step);o.actionTotal=action.seconds;o.actionLeft=action.seconds;if(o.id===selected){pick=null;drag=null;document.querySelector('.drag-ghost')?.remove();busy=true}return true}
function place(item){const o=state.orders.find(o=>o.id===selected);if(!o||o.action||modal||screen!=='game')return;const r=recipe(o);if(o.step>=r.steps.length||recipeViewFor===o.id)return;if(startAutomaticStep(o)){save();render();return;}if(r.steps[o.step]!==item){o.step=0;o.mistakes=(o.mistakes||0)+1;o.mistake='That was not the right ingredient or step. Start again — time has not reset.';pick=null;busy=false;sound(180);save();render();toast(o.mistake);return}delete o.mistake;pick=null;o.action=item;CafeAudio.preparation(item);o.actionTotal=item==='Brew'?4:(state.upgrades.includes('machine')?.5:1);o.actionLeft=o.actionTotal;busy=true;save();render()}

function serve(id){
 const o=state.orders.find(x=>x.id===id);if(!o||modal)return;
 const group=o.group?state.orders.filter(x=>x.group===o.group):[o];
 if(group.some(x=>x.action||x.step!==recipe(x).steps.length))return;
 const before=level(),late=o.remaining<=0;let total=0,tips=0,earned=0;
 for(const x of group){const r=recipe(x),base=late?Math.round(r.price*.6):r.price,tip=late?0:Math.round(r.tip*Math.max(0,Math.min(1,x.remaining/x.duration))),xp=late?5:10+Math.round(15*Math.max(0,Math.min(1,x.remaining/x.duration)));total+=base+tip;tips+=tip;earned+=xp;state.history.unshift({name:x.name,status:late?'Late':'Completed',base,tip,xp});}
 state.orders=state.orders.filter(x=>!group.includes(x));state.cash+=total;state.tips+=tips;state.xp+=earned;state.served+=group.length;state.rep=Math.max(0,Math.min(100,state.rep+(late?-2:1)));state.combo=late?0:state.combo+1;state.tutorial=3;state.history=state.history.slice(0,20);selected=null;focusId=null;state.nextArrival=3;
 toast((group.length>1?'Everyone served together! ':'Lovely, thank you! ')+`$${total} · +${earned} XP`);sound(900);finishVisit();save();render();
}
function familyOrderCard(o){const group=state.orders.filter(x=>x.group===o.group),ready=group.every(x=>x.step===recipe(x).steps.length&&!x.action);return `<section class="main-order glass family-card" aria-label="Group order"><span class="eyebrow">ONE TABLE · SERVE TOGETHER</span><h2>${esc(o.name)}</h2><p class="family-explain">Prepare ${group.length} items, then serve everyone at once.</p><div class="family-items">${group.map(x=>`<button data-action="select" data-id="${x.id}"><span>${recipe(x).icon}</span><span><b>${recipe(x).name}</b><small>${x.member} · ${x.step===recipe(x).steps.length?'Ready ✓':x.step?'In progress':'To prepare'}</small></span></button>`).join('')}</div><p data-time="${o.id}">${timeText(o)}</p>${ready?`<button class="primary wide" data-action="serve" data-id="${o.id}">Serve all ${group.length} items →</button>`:`<button class="primary wide" data-action="select" data-id="${group.find(x=>x.step<recipe(x).steps.length).id}">Prepare next item →</button>`}</section>`}
function levelReviewPanel(){const ids=level()>=4?['truffle-risotto','lobster-pasta','chocolate-fondant','delegation']:level()>=3?['pizza','pasta','mushroom-melt','travellers']:['sandwich','cheese-tomato','coffee','croissant','family'];return `<h2>Level selection</h2><p>Temporary review mode. Your saved café progress stays safe.</p><div class="level-picker">${[[1,'Tea stall · countryside customers'],[2,'Café · students and a family'],[3,'Restaurant · premium menu and new guests'],[4,'Grand hotel · luxury dining and business guests']].map(([n,t])=>`<button data-action="review-level" data-value="${n}">Level ${n}<small>${t}</small></button>`).join('')}</div>${reviewSave&&level()>=2?`<p>Try an order</p><div class="review-recipes">${ids.map(id=>`<button data-action="review-order" data-value="${id}">${id==='delegation'?'Business lunch · 3 dishes':id==='family'?'Family · 3 items':id==='travellers'?'Travelling friends · 2 dishes':RECIPES.find(r=>r.id===id).name}</button>`).join('')}</div>`:''}${reviewSave?'<button class="primary wide" data-action="leave-review">Return to my saved café</button>':''}`}
function startReview(target){if(!reviewSave)reviewSave=JSON.parse(JSON.stringify(state));state={...fresh(),name:state.name||'Owner',xp:(target-1)*100,levelNumber:target,cash:200,tutorial:3,seenIntro:true,recipeRevision:3};reviewRecipe=target>=4?'truffle-risotto':target>=3?'pizza':target===2?'sandwich':'green-tea';selected=null;focusId=null;modal=null;recipeViewFor=null;busy=false;screen='exterior';render()}
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action;if(a==='review-level'){startReview(Number(b.dataset.value));}else if(a==='review-order'){state.orders=[];selected=null;modal=null;reviewRecipe=b.dataset.value;screen='game';addOrder();}else if(a==='leave-review'){if(reviewSave){state=reviewSave;reviewSave=null;reviewRecipe=null;selected=null;modal=null;recipeViewFor=null;screen='exterior';render()}}else if(a==='music-toggle'){const owner=document.querySelector('#owner');if(owner)state.name=owner.value.trim();state.music=!(audioStarted&&state.music);audioStarted=true;CafeAudio.unlock().then(ok=>{if(!ok)toast('Audio could not start. Check your browser sound permission.');});audioSync();save();render();}else if(a==='test-audio'){CafeAudio.preview().then(ok=>toast(ok?'Playing a sound preview.':'Audio could not start. Check your browser sound permission.'));}else if(a==='next-family'){const group=state.orders.filter(x=>x.group===b.dataset.id);selected=group.find(x=>x.step<recipe(x).steps.length)?.id||null;recipeViewFor=null;pick=null;render()}else if(a==='enter'){const n=document.querySelector('#owner').value.trim();if(!n){toast('Enter your name to open your café.');document.querySelector('#owner').focus();return}audioStarted=true;CafeAudio.unlock();state.name=n;save();entering=true;render();setTimeout(()=>{entering=false;screen='game';state.seenIntro=true;if(state.journeyComplete)modal='complete';else if(!state.orders.length)addOrder(state.served===0);save();render()},1200)}else if(a==='focus'){focusId=b.dataset.id;selected=null;pick=null;render()}else if(a==='counter'){recipeViewFor=null;focusId=selected;selected=null;pick=null;render()}else if(a==='select'){selected=b.dataset.id;recipeViewFor=null;pick=null;focusId=selected;if(state.tutorial===0)state.tutorial=1;render()}else if(a==='serve')serve(b.dataset.id);else if(a==='close'){modal=null;render()}else if(['pause','shop','recipes','exterior','reset','levels'].includes(a)){if(screen==='exterior'){const field=document.querySelector('#owner');if(field){state.name=field.value.trim();save()}}modal=a;render()}else if(a==='buy'){const u=UPGRADES.find(u=>u.id===b.dataset.id);if(u&&state.cash>=u.cost&&level()>=u.level&&!state.upgrades.includes(u.id)){state.cash-=u.cost;state.upgrades.push(u.id);if(u.id==='plants')state.rep=Math.min(100,state.rep+5);save();toast(u.name+' added to your café.');render()}}else if(a==='confirm-reset'){reviewSave=null;reviewRecipe=null;state=fresh();selected=null;modal=null;screen='exterior';save();render()}});
app.addEventListener('click',e=>{if(e.target.closest('[data-recipe-toggle]')){recipeViewFor=selected;pick=null;drag=null;document.querySelector('.drag-ghost')?.remove();render();document.querySelector('[data-recipe-close]')?.focus()}else if(e.target.closest('[data-recipe-close]')){recipeViewFor=null;render();document.querySelector('[data-recipe-toggle]')?.focus()}});
app.addEventListener('keydown',e=>{if(e.key!=='Tab'||recipeViewFor!==selected||!selected)return;const buttons=[...document.querySelectorAll('#recipe-popover button')];if(e.shiftKey&&document.activeElement===buttons[0]){e.preventDefault();buttons.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===buttons.at(-1)){e.preventDefault();buttons[0]?.focus()}});
app.addEventListener('change',e=>{if(e.target.dataset.setting){state[e.target.dataset.setting]=e.target.checked;audioSync();save()}});
app.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-ingredient]');if(!b||b.disabled||modal||recipeViewFor===selected)return;drag={item:b.dataset.ingredient,x:e.clientX,y:e.clientY,moved:false};b.setPointerCapture(e.pointerId)});
app.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>6)drag.moved=true;if(!drag.moved)return;let g=document.querySelector('.drag-ghost');if(!g){g=document.createElement('div');g.className='drag-ghost';g.innerHTML=objectArt(drag.item);document.body.append(g)}g.style.left=e.clientX+'px';g.style.top=e.clientY+'px';const board=document.querySelector('#board'),r=board?.getBoundingClientRect();board?.classList.toggle('over',!!r&&e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)});
app.addEventListener('pointerup',e=>{if(!drag)return;const d=drag;drag=null;document.querySelector('.drag-ghost')?.remove();const board=document.querySelector('#board'),r=board?.getBoundingClientRect();board?.classList.remove('over');if(d.moved){if(r&&e.clientX>=r.left&&e.clientX<=r.right&&e.clientY>=r.top&&e.clientY<=r.bottom)place(d.item);else toast('Drop ingredients onto the preparation board.')}else{pick=d.item;toast(`${d.item} selected. Tap the preparation board.`)}});
app.addEventListener('pointercancel',()=>{drag=null;document.querySelector('.drag-ghost')?.remove();document.querySelector('#board')?.classList.remove('over')});
app.addEventListener('click',e=>{if(e.target.closest('#board')&&!e.target.closest('[data-action]')&&pick)place(pick)});
app.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.dataset.ingredient){e.preventDefault();pick=e.target.dataset.ingredient;toast(pick+' selected. Focus the board and press Enter.')}if((e.key==='Enter'||e.key===' ')&&e.target.id==='board'&&pick){e.preventDefault();place(pick)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='owner'){document.querySelector('[data-action="enter"]')?.click();return}if(e.key==='Escape'&&recipeViewFor){recipeViewFor=null;render();return}if(e.key==='Escape'&&screen==='game'){modal=modal?null:'pause';render()}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&screen==='game'){modal='pause';save();render()}});
setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,1);last=now;audioSync();if(screen!=='game'||modal||document.hidden)return;let changed=false;for(const o of state.orders){if(startAutomaticStep(o))changed=true;if(o.action){o.actionLeft-=dt;if(o.actionLeft<=0){o.step++;delete o.action;busy=false;startAutomaticStep(o);changed=true;}else if(o.id===selected){const bar=document.querySelector('#action-progress');if(bar)bar.style.width=100*(1-o.actionLeft/o.actionTotal)+'%';const countdown=document.querySelector('#auto-countdown');if(countdown)countdown.textContent=Math.max(1,Math.ceil(o.actionLeft))+'s'}}if(!state.relaxed)o.remaining-=dt;if(o.remaining<=-20){state.history.unshift({name:o.name,status:'Missed',base:0,tip:0,xp:0});if(!o.group||state.orders.find(x=>x.group===o.group)===o)state.rep=Math.max(0,state.rep-4);state.combo=0;toast(`${o.name} had to leave. No payment earned — a fresh start awaits.`);if(selected===o.id)selected=null;changed=true}}
const expired=state.orders.filter(o=>o.remaining<=-20);const departed=new Set(expired.map(o=>o.group||o.id));state.orders=state.orders.filter(o=>o.remaining>-20);for(const visit of departed)finishVisit();state.nextArrival-=dt;if(!modal&&!state.journeyComplete&&state.visitsStarted<3&&state.nextArrival<=0&&!state.orders.length){state.nextArrival=Math.max(10,22-level());addOrder(state.tutorial===0);changed=true}if(changed)render();else for(const o of state.orders){const t=document.querySelector(`[data-time="${o.id}"]`);if(t)t.textContent=timeText(o);const b=document.querySelector(`[data-bar="${o.id}"]`);if(b){b.classList.toggle('late',o.remaining<=0);b.firstElementChild.style.width=Math.max(0,o.remaining/o.duration*100)+'%'}const s=document.querySelector(`[data-status="${o.id}"]`);if(s)s.textContent=o.remaining<=0?'Late':o.step===recipe(o).steps.length?'Ready to serve':o.step?'Preparing':'Waiting';if(selected===o.id&&document.querySelector('#prep-clock')){const timer=document.querySelector('#prep-clock');timer.textContent=timeText(o);timer.classList.toggle('urgent',!state.relaxed&&o.remaining<=15)}}saveElapsed+=dt;if(saveElapsed>=2){saveElapsed=0;save()}},100);
window.addEventListener('beforeunload',save);render();
